SELECT SEGMENT, REVENUE_ACTUAL, REVENUE_BUDGET, REVENUE_VAR, EBITDA_ACTUAL, EBITDA_BUDGET, EBITDA_VAR
FROM SDP_DISNEYLANDPARIS.PUBLIC.DLP_SEGMENT_VARIANCE   -- last closed month 2026-10
ORDER BY IFF(SEGMENT = 'TOTAL', 1, 0), REVENUE_ACTUAL DESC;

SELECT HOTEL, REVPAR, FORECAST_REVPAR, REVPAR_GAP, OCCUPANCY_EFFECT, ADR_EFFECT, MAIN_DRIVER
FROM SDP_DISNEYLANDPARIS.PUBLIC.DLP_HOTEL_REVPAR_GAP   -- 2026-10, EUR per available room night
ORDER BY REVPAR_GAP;

SELECT SEGMENT, REVENUE_ACTUAL, REVENUE_BUDGET, REVENUE_VAR, EBITDA_ACTUAL, EBITDA_BUDGET, EBITDA_VAR
FROM SDP_DISNEYLANDPARIS.PUBLIC.DLP_SEGMENT_VARIANCE   -- last closed month 2026-10
ORDER BY IFF(SEGMENT = 'TOTAL', 1, 0), REVENUE_ACTUAL DESC;
